from pathlib import Path
import json
R=Path(__file__).resolve().parent
anchors=[z['attachment_proxies'] for z in json.loads((R/'gaze/sources.json').read_text())]
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>천사 레토 · 드래그와 시선</title><style>*{box-sizing:border-box}body{margin:0;background:#11182a;color:#efe5d4;font:16px system-ui;padding:32px}h1{font-size:25px}p{color:#b8bdcf}main{max-width:1080px;margin:auto}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}article{border:1px solid #34405c;border-radius:18px;padding:18px;background:#172035}img,canvas{display:block;max-width:100%;margin:auto}button,a{color:#f4dfa9}button{background:#28364f;border:1px solid #55617b;border-radius:9px;padding:9px;margin:4px}small{display:block;color:#adb9d0}canvas{touch-action:none;background:transparent}a{display:inline-block;margin-top:16px}</style><main><h1>천사 레토 · 비행과 마우스 따라보기</h1><p>레토 실제 몸 크기를 기준으로 표시해요. 타토는 푸른 별빛, 멜로디는 붉은 하트빛으로 함께 반응해요.</p><div class="grid"><article><h2>왼쪽 드래그</h2><img src="drag-left/review/drag-left.gif"><small>타토가 앞서고 멜로디가 따라오며 함께 비행해요.</small></article><article><h2>오른쪽 드래그</h2><img src="drag-right/review/drag-right.gif"><small>멜로디가 이끌고 타토가 뒤따라요.</small></article><article id="follow"><h2>마우스 360° 따라보기</h2><canvas width="320" height="360"></canvas><small id="label">이 영역 안에서 마우스를 움직여 보세요.</small><button id="auto">방향 둘러보기</button><button id="hold">현재 방향 고정</button><button id="bg">밝은 배경</button></article><article><h2>기본 대기 · 랜덤 변형</h2><img width="320" src="../gaze-left-v1-20261106/review/gaze-left.gif"><small>앞서 만든 왼쪽 바라보기 동작은 기본 대기에서 한 바퀴씩 랜덤으로 재생해요.</small></article></div><a href="../../review-gallery-20261105/index.html">모든 상태 모아보기 ↗</a></main><script>
const anchors=__ANCHORS__,canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),label=document.querySelector('#label');
let direction=0,auto=true,dark=true,last=0;const chars=[],backs=[];
function load(path){const i=new Image();i.src=path;return i}for(let i=0;i<16;i++)chars.push(load(`gaze/character/${String(i).padStart(2,'0')}.png`));for(let i=0;i<64;i++)backs.push(load(`gaze-back/${String(i).padStart(3,'0')}.png`));
canvas.addEventListener('pointermove',e=>{auto=false;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*320/r.width-151,y=178-(e.clientY-r.top)*360/r.height;if(Math.hypot(x,y)>10)direction=(Math.round(Math.atan2(x,y)/(Math.PI/8))+16)%16;label.textContent=`마우스 방향 ${direction*22.5}° · 이펙트는 계속 움직여요`;});
document.querySelector('#auto').onclick=()=>{auto=true};document.querySelector('#hold').onclick=()=>{auto=false};document.querySelector('#bg').onclick=e=>{dark=!dark;e.target.textContent=dark?'밝은 배경':'어두운 배경'};
function draw(t){ctx.fillStyle=dark?'#10182a':'#edf0f5';ctx.fillRect(0,0,320,360);if(auto)direction=Math.floor(t/350)%16;const side=224*544/448*1.06,x=(320-side)/2,y=320-484*side/544;const b=backs[Math.floor(t/50)%64];if(b.complete&&b.naturalWidth)ctx.drawImage(b,x,y,side,side);for(let actor=0;actor<2;actor++)for(let j=0;j<3;j++){const q=((t/1000+j*.15)%.8)/.8,a=anchors[direction][actor?'melody':'tato'],px=x+(a[0]+(actor?8:-8)*q)*side/544,py=y+(a[1]+6+28*q)*side/544;ctx.save();ctx.translate(px,py);ctx.fillStyle=actor?'#ff6e90':'#66caff';ctx.globalAlpha=.82*Math.sin(Math.PI*q)**1.2;ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=6;ctx.beginPath();if(!actor){for(let i=0;i<8;i++){let r=(i%2?2:7)*side/544,ang=i*Math.PI/4;ctx.lineTo(Math.sin(ang)*r,Math.cos(ang)*r)}}else{ctx.moveTo(0,4);ctx.bezierCurveTo(-9,-2,-5,-8,0,-4);ctx.bezierCurveTo(5,-8,9,-2,0,4)}ctx.fill();ctx.restore()}const c=chars[direction];if(c.complete&&c.naturalWidth)ctx.drawImage(c,x,y,side,side);requestAnimationFrame(draw)}requestAnimationFrame(draw);
</script>'''
(R/'index.html').write_text(html.replace('__ANCHORS__',json.dumps(anchors)))
print('Built interactive16direction review')
